    mont: { slug: "hoe-jas-aanpassen-antalya", title: "Kan een jas of gewatteerde jack worden aangepast?", desc: "Ja: mouwen en lengte inkorten, aanpassen, de rits vervangen en de voering herstellen. Bij gewatteerde kleding werken wij voorzichtig om de vulling niet…", h1: "Kan een jas of gewatteerde jack worden aangepast?", lead: "Ja: mouwen en lengte inkorten, aanpassen, de rits vervangen en de voering herstellen. Bij gewatteerde kleding werken wij voorzichtig om de vulling niet te beschadigen.", sections: [{ h: "Kort samengevat", p: ["Ja: mouwen en lengte inkorten, aanpassen, de rits vervangen en de voering herstellen. Bij gewatteerde kleding werken wij voorzichtig om de vulling niet te beschadigen."] }, { h: "Hoe brengt u het kledingstuk in Antalya", p: [`Wij halen het kledingstuk op en brengen het terug naar uw hotel, of u brengt het naar ons atelier in Konyaaltı, elke dag open van 08:00 tot 23:00. Stuur eerst een foto via WhatsApp, dan noemen wij prijs en doorlooptijd. ${T.nl.all}`] }, { h: "Een praktische tip", p: ["Meld of de jas waterdicht of technisch is: bij sommige naden is een bijzondere aanpak nodig."] }], faq: [["Hoe lang duurt het?", `${T.nl.all}`], ["Wat kost het?", "De prijs hangt af van het kledingstuk en het werk. Stuur een foto via WhatsApp, dan noemen wij de prijs voordat wij beginnen."]], wa: "Hallo, ik heb een vraag over: Kan een jas of gewatteerde jack worden aangepast." },
