export const hzUrl = (l: ILang, h: HzId) => `/${l}/${HZ[l][h].slug}`;
export const parseHz = (l: ILang, slug: string): HzId | undefined => HZ_IDS.find((h) => HZ[l][h].slug === slug);

const SITE_ABS = 'https://swaphubs.com';
/** Rehber → TR/EN/RU/DE hizmet sayfasının Türkçe slug'ı (SERVICES). */
export const HZ_SVC: Record<HzId, string> = {
  paca: 'pantolon-paca-kisaltma', kot: 'kot-pantolon-paca-kisaltma', bel: 'bel-daraltma', fermuar: 'fermuar-degisimi-tamiri',
  elbise: 'elbise-dikimi', gelinlik: 'gelinlik-abiye-tadilati', abiye: 'abiye-tadilati-gece-kiyafetleri', kol: 'kol-boyu-kisaltma',
  takim: 'takim-elbise-ceket-tadilati', mont: 'mont-palto-tadilati', deri: 'deri-ceket-pantolon-tadilati', pantolon: 'pantolon-tadilati',
  beden: 'olcuye-gore-beden-ayarlama', tamir: 'kiyafet-tamiri-onarimi',
};
const SIX: ILang[] = ['es', 'fr', 'pl', 'uk', 'nl', 'ar'];
export const hzSix = (h: HzId): Record<string, string> => Object.fromEntries(SIX.map((l) => [l, `${SITE_ABS}${hzUrl(l, h)}`]));
export const hzCore = (h: HzId): Record<string, string> => {
  const sv = SERVICES.find((x) => x.slug.tr === HZ_SVC[h]);
  return sv ? Object.fromEntries((['tr', 'en', 'ru', 'de'] as const).map((l) => [l, `${SITE_ABS}${serviceUrl(l, sv)}`])) : {};
};
export const hzLanguages = (h: HzId): Record<string, string> => {
  const c = hzCore(h);
  return { ...c, ...hzSix(h), ...(c.tr ? { 'x-default': c.tr } : {}) };
};
/** Mevcut TR/EN/RU/DE hizmet sayfası için eklenecek 6 dil karşılığı. */
export const hzSixForService = (trSlug: string): Record<string, string> => {
  const h = HZ_IDS.find((x) => HZ_SVC[x] === trSlug);
  return h ? hzSix(h) : {};
};
